  const lower = String(text || '').toLowerCase();
  return lower.includes(':: login') || lower.includes('login/check') || lower.includes('assets/dashboard/css/login.css') || lower.includes('name="password"') || lower.includes("name='password'");
};

async function requestFull(options) {
  const requestOptions = {
    method: options.method || 'GET',
    url: options.url,
    headers: options.headers || {},
    body: options.body,
    json: false,
    returnFullResponse: true,
    resolveWithFullResponse: true,
    simple: false,
    timeout: 30000,
  };

  if (this?.helpers?.httpRequest) {
    const response = await this.helpers.httpRequest(requestOptions);
    if (response && typeof response === 'object' && (response.headers || Object.prototype.hasOwnProperty.call(response, 'body'))) {
      const body = typeof response.body === 'string' ? response.body : JSON.stringify(response.body ?? '');
      return { statusCode: response.statusCode || response.status || 0, headers: response.headers || {}, body };
    }
    return { statusCode: 0, headers: {}, body: typeof response === 'string' ? response : JSON.stringify(response ?? '') };
  }

  if (typeof fetch !== 'function') throw new Error('No HTTP helper available inside n8n Code node.');
  const response = await fetch(options.url, {
    method: options.method || 'GET',
    headers: options.headers || {},
    body: options.body,
    redirect: 'manual',
  });
  const body = await response.text();
  return { statusCode: response.status, headers: response.headers, body };
}

